import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry conv2d_nchw(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W,
    .param .u32 OC,
    .param .u32 KH,
    .param .u32 KW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 OH,
    .param .u32 OW,
    .param .u32 has_bias
)
{
    .reg .pred  p0, p1, p2, p3, p4;
    .reg .b32   rN, rC, rH, rW, rOC, rKH, rKW, rSH, rSW, rPH, rPW, rDH, rDW, rOH, rOW, rHasB;
    .reg .b32   r_tid, r_bid, r_bdim, r_idx32;
    .reg .b32   n, oc, oh, ow, t1, t2;
    .reg .b64   x, w, b, y;
    .reg .b64   total64, tmp64, idx64;

    .reg .f32   acc, vx, vw, vb;

    // Load params
    ld.param.u64 x, [x_ptr];
    ld.param.u64 w, [w_ptr];
    ld.param.u64 b, [b_ptr];
    ld.param.u64 y, [y_ptr];
    ld.param.u32 rN, [N];
    ld.param.u32 rC, [C];
    ld.param.u32 rH, [H];
    ld.param.u32 rW, [W];
    ld.param.u32 rOC, [OC];
    ld.param.u32 rKH, [KH];
    ld.param.u32 rKW, [KW];
    ld.param.u32 rSH, [stride_h];
    ld.param.u32 rSW, [stride_w];
    ld.param.u32 rPH, [pad_h];
    ld.param.u32 rPW, [pad_w];
    ld.param.u32 rDH, [dil_h];
    ld.param.u32 rDW, [dil_w];
    ld.param.u32 rOH, [OH];
    ld.param.u32 rOW, [OW];
    ld.param.u32 rHasB, [has_bias];

    // Global linear thread id
    mov.u32 r_tid, %tid.x;
    mov.u32 r_bid, %ctaid.x;
    mov.u32 r_bdim, %ntid.x;
    mad.lo.s32 r_idx32, r_bid, r_bdim, r_tid;

    // total = N*OC*OH*OW (64-bit)
    mul.wide.u32 total64, rN, rOC;      // N*OC -> 64-bit
    mul.wide.u32 tmp64, rOH, rOW;       // OH*OW -> 64-bit
    mul.lo.u64 total64, total64, tmp64; // total64 = (N*OC)*(OH*OW)

    cvt.u64.u32 idx64, r_idx32;
    setp.ge.u64 p0, idx64, total64;
    @p0 ret;

    // Decompose index into (n, oc, oh, ow)
    // ow = idx % OW
    rem.u32 ow, r_idx32, rOW;
    div.u32 t1, r_idx32, rOW;     // t1 = idx / OW
    rem.u32 oh, t1, rOH;
    div.u32 t2, t1, rOH;          // t2 = t1 / OH
    rem.u32 oc, t2, rOC;
    div.u32 n, t2, rOC;

    // acc = bias[oc] if present
    mov.f32 acc, 0f00000000;
    setp.eq.u32 p1, rHasB, 0;
    @p1 bra NO_BIAS;
        {
            .reg .b64 b_off;
            mul.wide.u32 b_off, oc, 4;
            add.s64 b_off, b, b_off;
            ld.global.f32 vb, [b_off];
            add.f32 acc, acc, vb;
        }
NO_BIAS:

    // base_ih = oh*stride_h - pad_h, base_iw = ow*stride_w - pad_w
    .reg .s32 base_ih, base_iw;
    mul.lo.s32 base_ih, oh, rSH;
    sub.s32 base_ih, base_ih, rPH;
    mul.lo.s32 base_iw, ow, rSW;
    sub.s32 base_iw, base_iw, rPW;

    // Loop over input channels, kh, kw
    .reg .b32 ic, kh, kw;
    mov.u32 ic, 0;

IC_LOOP:
    setp.ge.u32 p2, ic, rC;
    @p2 bra IC_DONE;

    mov.u32 kh, 0;
KH_LOOP:
    setp.ge.u32 p3, kh, rKH;
    @p3 bra KH_DONE;

    // ih = base_ih + kh * dil_h
    .reg .s32 ih, iw;
    mad.lo.s32 ih, kh, rDH, base_ih;

    // if (ih < 0 || ih >= H) continue kh
    setp.lt.s32 p4, ih, 0;
    @p4 bra KH_CONT;
    setp.ge.s32 p4, ih, rH;
    @p4 bra KH_CONT;

    mov.u32 kw, 0;
KW_LOOP:
    setp.ge.u32 p4, kw, rKW;
    @p4 bra KW_DONE;

    // iw = base_iw + kw * dil_w
    mad.lo.s32 iw, kw, rDW, base_iw;

    // if (iw < 0 || iw >= W) continue kw
    setp.lt.s32 p4, iw, 0;
    @p4 bra KW_CONT;
    setp.ge.s32 p4, iw, rW;
    @p4 bra KW_CONT;

    // Load x[n, ic, ih, iw]
    {
        .reg .b32 tC1;
        .reg .b64 x_e, x_b;
        .reg .s64 ih64;
        mad.lo.u32 tC1, n, rC, ic;                 // n*C + ic
        mul.wide.u32 x_e, tC1, rH;                 // * H -> 64
        cvt.s64.s32 ih64, ih;
        add.s64 x_e, x_e, ih64;                    // + ih
        .reg .b64 rW64;
        cvt.u64.u32 rW64, rW;
        mul.lo.u64 x_e, x_e, rW64;                 // * W
        .reg .s64 iw64;
        cvt.s64.s32 iw64, iw;
        add.s64 x_e, x_e, iw64;                    // + iw
        mul.lo.u64 x_b, x_e, 4;                    // * sizeof(float)
        add.s64 x_b, x, x_b;
        ld.global.f32 vx, [x_b];
    }

    // Load w[oc, ic, kh, kw]
    {
        .reg .b32 tC2;
        .reg .b64 w_e, w_b;
        mad.lo.u32 tC2, oc, rC, ic;                // oc*C + ic
        mul.wide.u32 w_e, tC2, rKH;                // * KH -> 64
        .reg .u64 kh64;
        cvt.u64.u32 kh64, kh;
        add.s64 w_e, w_e, kh64;                    // + kh
        .reg .b64 rKW64;
        cvt.u64.u32 rKW64, rKW;
        mul.lo.u64 w_e, w_e, rKW64;                // * KW
        .reg .u64 kw64;
        cvt.u64.u32 kw64, kw;
        add.s64 w_e, w_e, kw64;                    // + kw
        mul.lo.u64 w_b, w_e, 4;                    // * sizeof(float)
        add.s64 w_b, w, w_b;
        ld.global.f32 vw, [w_b];
    }

    // acc += vx * vw
    fma.rn.f32 acc, vx, vw, acc;

KW_CONT:
    add.u32 kw, kw, 1;
    bra KW_LOOP;
KW_DONE:

KH_CONT:
    add.u32 kh, kh, 1;
    bra KH_LOOP;
KH_DONE:

    add.u32 ic, ic, 1;
    bra IC_LOOP;
IC_DONE:

    // Store y[n, oc, oh, ow]
    {
        .reg .b32 tOC1;
        .reg .b64 y_e, y_b;
        mad.lo.u32 tOC1, n, rOC, oc;               // n*OC + oc
        mul.wide.u32 y_e, tOC1, rOH;               // * OH -> 64
        .reg .u64 oh64;
        cvt.u64.u32 oh64, oh;
        add.s64 y_e, y_e, oh64;                    // + oh
        .reg .b64 rOW64;
        cvt.u64.u32 rOW64, rOW;
        mul.lo.u64 y_e, y_e, rOW64;                // * OW
        .reg .u64 ow64;
        cvt.u64.u32 ow64, ow;
        add.s64 y_e, y_e, ow64;                    // + ow
        mul.lo.u64 y_b, y_e, 4;                    // * sizeof(float)
        add.s64 y_b, y, y_b;
        st.global.f32 [y_b], acc;
    }

    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_nchw")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1), bias: bool = False):
        super().__init__()
        # Normalize parameters to tuples
        if isinstance(kernel_size, int):
            kh, kw = kernel_size, kernel_size
        else:
            kh, kw = int(kernel_size[0]), int(kernel_size[1])
        if isinstance(stride, int):
            sh, sw = stride, stride
        else:
            sh, sw = int(stride[0]), int(stride[1])
        if isinstance(padding, int):
            ph, pw = padding, padding
        else:
            ph, pw = int(padding[0]), int(padding[1])
        if isinstance(dilation, int):
            dh, dw = dilation, dilation
        else:
            dh, dw = int(dilation[0]), int(dilation[1])

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = (kh, kw)
        self.stride = (sh, sw)
        self.padding = (ph, pw)
        self.dilation = (dh, dw)
        self.bias_flag = bool(bias)

        # Parameters
        self.weight = nn.Parameter(torch.empty(self.out_channels, self.in_channels, kh, kw))
        if self.bias_flag:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        # Initialize like nn.Conv2d
        self.reset_parameters()

    def reset_parameters(self):
        # Match torch.nn.Conv2d default init: kaiming_uniform_(a=√5) for weights; bias uniform(-bound, bound) with bound = 1/sqrt(fan_in)
        a = math.sqrt(5.0)
        init.kaiming_uniform_(self.weight, a=a, mode="fan_in", nonlinearity="leaky_relu")
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew.forward requires CUDA tensor input.")
        if x.dtype != torch.float32:
            raise RuntimeError("ModelNew.forward supports only float32 tensors.")

        N, C, H, W = x.shape
        OC = self.out_channels
        KH, KW = self.kernel_size
        SH, SW = self.stride
        PH, PW = self.padding
        DH, DW = self.dilation

        # Output dimensions following PyTorch Conv2d formula
        OH = (H + 2 * PH - (DH * (KH - 1) + 1)) // SH + 1
        OW = (W + 2 * PW - (DW * (KW - 1) + 1)) // SW + 1
        if OH <= 0 or OW <= 0:
            raise RuntimeError("Invalid output dimensions computed for convolution.")

        # Ensure parameter shapes match
        assert C == self.in_channels, "Input channels mismatch."

        x_c = x.contiguous()
        w_c = self.weight.contiguous()
        y = torch.empty((N, OC, OH, OW), device=x.device, dtype=x.dtype)
        has_bias = 1 if self.bias is not None else 0

        module = _get_ptx_module()
        total = N * OC * OH * OW
        block_x = 256
        grid_x = (total + block_x - 1) // block_x

        # Prepare bias pointer or null
        b_arg = self.bias if self.bias is not None else u64(0)

        module.launch(
            "conv2d_nchw",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x_c,
                w_c,
                b_arg,
                y,
                i32(N),
                i32(C),
                i32(H),
                i32(W),
                i32(OC),
                i32(KH),
                i32(KW),
                i32(SH),
                i32(SW),
                i32(PH),
                i32(PW),
                i32(DH),
                i32(DW),
                i32(OH),
                i32(OW),
                i32(has_bias),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x_c.device),
        )
        return y

